16→  constructor(endpoint: string, authToken?: string) {
17→    // Normalize: strip trailing slash
18→    this.endpoint = endpoint.replace(/\/+$/, '');
19→    this.authToken = authToken;
20→  }
21→
22→  /**
23→   * Upload and pin data to the Kubo node.
24→   * Uses /api/v0/add with pin=true and cid-version=1 for CIDv1.
25→   */
26→  async pin(data: Uint8Array, _name?: string): Promise<PinResult> {
27→    const url = `${this.endpoint}/api/v0/add?pin=true&cid-version=1`;
28→    const formData = new FormData();
29→    // Pass typed array directly to Blob (never use .buffer to avoid offset issues)
30→    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
31→    formData.append('file', blob);
32→
33→    const response = await fetch(url, {
34→      method: 'POST',
35→      body: formData,
36→      headers: this.buildHeaders(),
37→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
38→    });
39→
40→    if (!response.ok) {
41→      const errorText = await response.text();
42→      throw new Error(`Kubo add failed: ${response.status} - ${errorText}`);
43→    }
44→
45→    // Kubo returns ndjson; for a single file, parse the first (only) line
46→    const text = await response.text();
47→    const result = JSON.parse(text) as { Hash: string; Size: string };
48→    return {
49→      cid: result.Hash,
50→      size: parseInt(result.Size, 10),
51→    };
52→  }
