54→  /**
55→   * Remove a pin by CID.
56→   * Ignores "not pinned" errors for idempotency.
57→   */
58→  async unpin(cid: string): Promise<void> {
59→    const url = `${this.endpoint}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}`;
60→
61→    const response = await fetch(url, {
62→      method: 'POST',
63→      headers: this.buildHeaders(),
64→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
65→    });
66→
67→    if (!response.ok) {
68→      const errorText = await response.text();
69→      // "not pinned" means already unpinned -- treat as success (idempotent)
70→      if (errorText.toLowerCase().includes('not pinned')) {
71→        return;
72→      }
73→      throw new Error(`Kubo unpin failed: ${response.status} - ${errorText}`);
74→    }
75→  }
